INSERT INTO t_p22961065_vector_driving_instr.pdd_topics (category_id, slug, title, content, sort_order)
SELECT id, 'osnovnye-polozheniya-manevr', 'Начало движения и манёврирование', 'Перед началом движения, перестроением, поворотом или разворотом водитель обязан подать сигнал световыми указателями поворота, а при их отсутствии или неисправности — рукой. Подача сигнала не даёт водителю преимущества и не освобождает его от принятия мер предосторожности. Сигнал должен подаваться заблаговременно до начала выполнения манёвра и прекращён немедленно после его завершения. Перед выполнением манёвра водитель обязан убедиться, что это будет безопасно и не создаст помех другим участникам движения.', 1
FROM t_p22961065_vector_driving_instr.pdd_categories WHERE slug='nachalo-dvizheniya';

INSERT INTO t_p22961065_vector_driving_instr.pdd_topics (category_id, slug, title, content, sort_order)
SELECT id, 'raspolozhenie-ts', 'Расположение транспортных средств на проезжей части', 'Количество полос движения на дорогах, где границы полос не обозначены разметкой, определяется водителями с учётом ширины проезжей части, габаритов ТС и необходимых интервалов между ними. При этом на дорогах с двусторонним движением, имеющих три полосы, обозначенные разметкой, средняя полоса предназначена для движения в обоих направлениях. Тихоходные транспортные средства, а также ТС, скорость которых по техническим причинам ниже установленной, должны двигаться по крайней правой полосе.', 1
FROM t_p22961065_vector_driving_instr.pdd_categories WHERE slug='raspolozhenie';

INSERT INTO t_p22961065_vector_driving_instr.pdd_topics (category_id, slug, title, content, sort_order)
SELECT id, 'skorostnoy-rezhim', 'Скоростной режим', 'В населённых пунктах разрешается движение со скоростью не более 60 км/ч, а в жилых зонах и на дворовых территориях — не более 20 км/ч. Вне населённых пунктов легковым автомобилям разрешено движение по автомагистралям со скоростью не более 110 км/ч, по прочим дорогам — не более 90 км/ч. При возникновении опасности для движения водитель обязан принять меры к снижению скорости вплоть до остановки транспортного средства.', 1
FROM t_p22961065_vector_driving_instr.pdd_categories WHERE slug='skorost';

INSERT INTO t_p22961065_vector_driving_instr.pdd_topics (category_id, slug, title, content, sort_order)
SELECT id, 'obgon-vstrechny-razjezd', 'Обгон и встречный разъезд', 'Обгон запрещён на пешеходных переходах, на железнодорожных переездах и ближе 100 метров перед ними, на мостах, эстакадах, путепроводах и под ними, а также в конце подъёма и на других участках с ограниченной видимостью. Перед началом обгона водитель обязан убедиться, что полоса движения, на которую он собирается выехать, свободна на достаточном для обгона расстоянии и что во время обгона он не создаст опасности для движения и помех другим участникам.', 1
FROM t_p22961065_vector_driving_instr.pdd_categories WHERE slug='obgon';

INSERT INTO t_p22961065_vector_driving_instr.pdd_topics (category_id, slug, title, content, sort_order)
SELECT id, 'ostanovka-stoyanka-pravila', 'Правила остановки и стоянки', 'Остановка и стоянка запрещаются на пешеходных переходах и ближе 5 метров перед ними, на местах остановки маршрутных транспортных средств, на железнодорожных переездах, в тоннелях, ближе 15 метров от мест остановки маршрутных ТС. Транспортное средство должно быть остановлено или поставлено на стоянку на правой стороне дороги параллельно краю проезжей части. Постановка на стоянку с целью длительной остановки на автомагистралях запрещена, кроме специально обозначенных мест.', 1
FROM t_p22961065_vector_driving_instr.pdd_categories WHERE slug='ostanovka-stoyanka';

INSERT INTO t_p22961065_vector_driving_instr.pdd_topics (category_id, slug, title, content, sort_order)
SELECT id, 'prioritet-marshrutnyh-ts', 'Приоритет маршрутных транспортных средств', 'При приближении маршрутного транспортного средства (автобуса, троллейбуса) с остановки, обозначенной соответствующим знаком, водители других транспортных средств обязаны уступить ему дорогу для выполнения манёвра отъезда. Вне населённых пунктов водитель обязан уступить дорогу транспортному средству с включёнными проблесковым маячком синего цвета и специальным звуковым сигналом независимо от направления его движения.', 1
FROM t_p22961065_vector_driving_instr.pdd_categories WHERE slug='prioritet-transporta';

INSERT INTO t_p22961065_vector_driving_instr.pdd_topics (category_id, slug, title, content, sort_order)
SELECT id, 'perevozka-lyudey-gruzov', 'Перевозка людей и грузов', 'Перевозка людей в кузове грузового автомобиля с бортовой платформой разрешается, если он оборудован для перевозки людей в соответствии с установленными требованиями. Перевозка детей допускается только в специальных удерживающих устройствах, соответствующих весу и росту ребёнка, либо с использованием иных средств, позволяющих пристегнуть ребёнка с помощью ремней безопасности. Груз, перевозимый на ТС, не должен ограничивать водителю обзор, ухудшать управляемость и закрывать световые приборы, номерные знаки.', 1
FROM t_p22961065_vector_driving_instr.pdd_categories WHERE slug='perevozka-passazhirov';

INSERT INTO t_p22961065_vector_driving_instr.pdd_topics (category_id, slug, title, content, sort_order)
SELECT id, 'neispravnosti-ekspluatatsiya', 'Неисправности, при которых запрещена эксплуатация ТС', 'Запрещается эксплуатация транспортного средства при неисправности рабочей тормозной системы, рулевого управления, тягово-сцепного устройства, негорящих или неисправных внешних световых приборах в тёмное время суток, неисправных стеклоочистителях со стороны водителя во время дождя или снегопада. При возникновении таких неисправностей в пути водитель должен устранить их, а если это невозможно — следовать к месту стоянки или ремонта с соблюдением необходимых мер предосторожности.', 1
FROM t_p22961065_vector_driving_instr.pdd_categories WHERE slug='neispravnosti';

INSERT INTO t_p22961065_vector_driving_instr.pdd_topics (category_id, slug, title, content, sort_order)
SELECT id, 'otvetstvennost-voditelya', 'Ответственность водителя', 'За нарушение Правил дорожного движения предусмотрена административная, а в отдельных случаях уголовная ответственность. Управление транспортным средством в состоянии опьянения, а также передача управления лицу, находящемуся в состоянии опьянения, влечёт лишение права управления транспортными средствами и административный штраф. Оставление места дорожно-транспортного происшествия его участником является грубым нарушением и влечёт лишение права управления либо административный арест.', 1
FROM t_p22961065_vector_driving_instr.pdd_categories WHERE slug='otvetstvennost';

INSERT INTO t_p22961065_vector_driving_instr.pdd_topics (category_id, slug, title, content, sort_order)
SELECT id, 'osnovy-bezopasnosti', 'Основы безопасности дорожного движения', 'Ремень безопасности должен быть пристёгнут водителем и всеми пассажирами транспортного средства во время движения. При дорожно-транспортном происшествии водитель обязан немедленно остановить транспортное средство, включить аварийную сигнализацию, выставить знак аварийной остановки, не перемещать предметы, имеющие отношение к происшествию, и принять меры для оказания первой помощи пострадавшим, вызвать скорую помощь и полицию.', 1
FROM t_p22961065_vector_driving_instr.pdd_categories WHERE slug='bezopasnost';
